def solve(inp):
    from collections import Counter
    H,W=len(inp),len(inp[0])
    bg=Counter(x for r in inp for x in r).most_common(1)[0][0]
    out=[row[:] for row in inp]
    # find maximal diagonal runs (both diag directions) of same non-bg color, len>=2
    seen=set()
    def ray(r,c,dr,dc,col):
        # extend from (r,c) along (dr,dc) over background until blocked/edge
        rr,cc=r+dr,c+dc
        while 0<=rr<H and 0<=cc<W and inp[rr][cc]==bg:
            out[rr][cc]=col; rr+=dr; cc+=dc
    for r in range(H):
        for c in range(W):
            col=inp[r][c]
            if col==bg: continue
            for dr,dc in ((1,1),(1,-1)):
                if (r,c,(dr,dc)) in seen: continue
                # collect maximal run through (r,c) along this diagonal
                run=[(r,c)]
                rr,cc=r+dr,c+dc
                while 0<=rr<H and 0<=cc<W and inp[rr][cc]==col:
                    run.append((rr,cc)); seen.add((rr,c c if False else cc,(dr,dc))); rr+=dr; cc+=dc
                rr,cc=r-dr,c-dc
                while 0<=rr<H and 0<=cc<W and inp[rr][cc]==col:
                    run.insert(0,(rr,cc)); seen.add((rr,cc,(dr,dc))); rr-=dr; cc-=dc
                if len(run)>=2:
                    a,b=run[0],run[-1]
                    ray(a[0],a[1],-dr,-dc,col)
                    ray(b[0],b[1],dr,dc,col)
    return out
